import{_ as a,o,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const r="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_04_01_layers.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_04_02_precedence.png",c="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_04_03_model_matrix.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_04_04_latency.png",s="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_04_05_diagnosis.png",d="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_04_06_reproducible.png",x=JSON.parse('{"title":"别再乱调 config.toml：Codex 配置、模型选择与速度优化全解","description":"许多“模型不听话”的问题，根因其实是配置层级、工作目录、权限、工具或项目规则不一致。OpenAI Docs 把 Codex 配置拆成个人默认、项目配置、Profile 与一次性覆盖，并强调不同入口共享主要配置层。理解覆盖关系，比背诵某个版本的全部配置键更重要。","frontmatter":{"title":"别再乱调 config.toml：Codex 配置、模型选择与速度优化全解","description":"许多“模型不听话”的问题，根因其实是配置层级、工作目录、权限、工具或项目规则不一致。OpenAI Docs 把 Codex 配置拆成个人默认、项目配置、Profile 与一次性覆盖，并强调不同入口共享主要配置层。理解覆盖关系，比背诵某个版本的全部配置键更重要。","date":"2026-08-10","topic":"AI 底层学习","section":"OpenAI官方文档解读","readingTime":5,"source":"2026-08-10/ai_codex_official_04_configuration_models.md","status":"archived","cover":"/article-assets/2026-08-10/ai_codex_official_04_01_layers.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"别再乱调 config.toml：Codex 配置、模型选择与速度优化全解"}],["meta",{"property":"og:description","content":"许多“模型不听话”的问题，根因其实是配置层级、工作目录、权限、工具或项目规则不一致。OpenAI Docs 把 Codex 配置拆成个人默认、项目配置、Profile 与一次性覆盖，并强调不同入口共享主要配置层。理解覆盖关系，比背诵某个版本的全部配置键更重要。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_04_01_layers.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"别再乱调 config.toml：Codex 配置、模型选择与速度优化全解"}],["meta",{"name":"twitter:description","content":"许多“模型不听话”的问题，根因其实是配置层级、工作目录、权限、工具或项目规则不一致。OpenAI Docs 把 Codex 配置拆成个人默认、项目配置、Profile 与一次性覆盖，并强调不同入口共享主要配置层。理解覆盖关系，比背诵某个版本的全部配置键更重要。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_04_01_layers.png"}],["meta",{"name":"robots","content":"noindex,follow"}]],"search":false,"prev":false,"next":false},"headers":[],"relativePath":"archive/ai-codex-official-04-configuration-models.md","filePath":"archive/ai-codex-official-04-configuration-models.md","lastUpdated":null}'),p={name:"archive/ai-codex-official-04-configuration-models.md"};function h(_,e,f,m,u,g){return o(),t("div",null,[...e[0]||(e[0]=[i('<blockquote><p>本文为历史归档版本，不再更新。请阅读<a href="/Nav2ArticlesSite/ai/openai-codex-complete-guide">当前版本</a>。</p></blockquote><h1 id="别再乱调-config-toml-codex-配置、模型选择与速度优化全解" tabindex="-1">别再乱调 config.toml：Codex 配置、模型选择与速度优化全解 <a class="header-anchor" href="#别再乱调-config-toml-codex-配置、模型选择与速度优化全解" aria-label="Permalink to &quot;别再乱调 config.toml：Codex 配置、模型选择与速度优化全解&quot;">​</a></h1><p>许多“模型不听话”的问题，根因其实是配置层级、工作目录、权限、工具或项目规则不一致。OpenAI Docs 把 Codex 配置拆成个人默认、项目配置、Profile 与一次性覆盖，并强调不同入口共享主要配置层。理解覆盖关系，比背诵某个版本的全部配置键更重要。</p><h2 id="一、配置与项目知识不是同一层" tabindex="-1">一、配置与项目知识不是同一层 <a class="header-anchor" href="#一、配置与项目知识不是同一层" aria-label="Permalink to &quot;一、配置与项目知识不是同一层&quot;">​</a></h2><h3 id="_1-1-配置决定默认运行姿势" tabindex="-1">1.1 配置决定默认运行姿势 <a class="header-anchor" href="#_1-1-配置决定默认运行姿势" aria-label="Permalink to &quot;1.1 配置决定默认运行姿势&quot;">​</a></h3><p>模型、推理强度、权限、功能开关、MCP、Hooks 和界面行为属于配置。它们回答“Codex 默认怎样运行”。</p><h3 id="_1-2-agents-md-决定项目做事规则" tabindex="-1">1.2 AGENTS.md 决定项目做事规则 <a class="header-anchor" href="#_1-2-agents-md-决定项目做事规则" aria-label="Permalink to &quot;1.2 AGENTS.md 决定项目做事规则&quot;">​</a></h3><p>构建命令、代码风格、目录边界和完成标准属于项目指令。它回答“在这个仓库应该怎样工作”。把项目百科塞进 <code>config.toml</code>，会让规则难以审查与共享。</p><h3 id="_1-3-prompt-决定本次任务" tabindex="-1">1.3 Prompt 决定本次任务 <a class="header-anchor" href="#_1-3-prompt-决定本次任务" aria-label="Permalink to &quot;1.3 Prompt 决定本次任务&quot;">​</a></h3><p>一次性的目标、文件范围和特殊约束应留在当前会话。不要为了一个临时任务修改全局默认。</p><p><img src="'+r+'" alt="图 1：配置、项目规则与当前 Prompt 的职责边界"></p><h2 id="二、配置优先级必须可解释" tabindex="-1">二、配置优先级必须可解释 <a class="header-anchor" href="#二、配置优先级必须可解释" aria-label="Permalink to &quot;二、配置优先级必须可解释&quot;">​</a></h2><h3 id="_2-1-个人配置提供跨项目默认" tabindex="-1">2.1 个人配置提供跨项目默认 <a class="header-anchor" href="#_2-1-个人配置提供跨项目默认" aria-label="Permalink to &quot;2.1 个人配置提供跨项目默认&quot;">​</a></h3><p>用户级 <code>config.toml</code> 适合模型偏好、常用 Profile 和个人工具连接。默认值应保守，避免一个高权限项目习惯扩散到所有仓库。</p><h3 id="_2-2-项目配置提供可信仓库默认" tabindex="-1">2.2 项目配置提供可信仓库默认 <a class="header-anchor" href="#_2-2-项目配置提供可信仓库默认" aria-label="Permalink to &quot;2.2 项目配置提供可信仓库默认&quot;">​</a></h3><p>仓库级 <code>.codex/config.toml</code> 可以共享项目需要的配置，但只有在信任仓库时才应加载。外部仓库中的配置本身也属于不可信输入。</p><h3 id="_2-3-命令行覆盖只服务一次运行" tabindex="-1">2.3 命令行覆盖只服务一次运行 <a class="header-anchor" href="#_2-3-命令行覆盖只服务一次运行" aria-label="Permalink to &quot;2.3 命令行覆盖只服务一次运行&quot;">​</a></h3><p>临时参数适合诊断或比较，不应成为团队不可见的长期事实。任务结束后要能从版本化配置重建行为。</p><h3 id="_2-4-profile-让场景切换显式化" tabindex="-1">2.4 Profile 让场景切换显式化 <a class="header-anchor" href="#_2-4-profile-让场景切换显式化" aria-label="Permalink to &quot;2.4 Profile 让场景切换显式化&quot;">​</a></h3><p>只读审计、本地开发和 CI 可以使用不同 Profile。Profile 名称应表达用途，并与实际权限、模型和工具条件一致。</p><p><img src="'+l+'" alt="图 2：个人、项目、Profile 与一次性覆盖的生效关系"></p><h2 id="三、模型选择从任务特征开始" tabindex="-1">三、模型选择从任务特征开始 <a class="header-anchor" href="#三、模型选择从任务特征开始" aria-label="Permalink to &quot;三、模型选择从任务特征开始&quot;">​</a></h2><h3 id="_3-1-复杂度决定推理需求" tabindex="-1">3.1 复杂度决定推理需求 <a class="header-anchor" href="#_3-1-复杂度决定推理需求" aria-label="Permalink to &quot;3.1 复杂度决定推理需求&quot;">​</a></h3><p>机械修改、查找符号和固定格式转换通常不需要最高推理强度；跨模块设计、陌生系统诊断和长时间 Agent 任务需要更强规划。</p><h3 id="_3-2-风险决定验证强度" tabindex="-1">3.2 风险决定验证强度 <a class="header-anchor" href="#_3-2-风险决定验证强度" aria-label="Permalink to &quot;3.2 风险决定验证强度&quot;">​</a></h3><p>简单但涉及身份、支付、迁移或公开接口的任务，仍需要严格 Review。模型强度不能替代安全与测试。</p><h3 id="_3-3-工具条件可能比模型更关键" tabindex="-1">3.3 工具条件可能比模型更关键 <a class="header-anchor" href="#_3-3-工具条件可能比模型更关键" aria-label="Permalink to &quot;3.3 工具条件可能比模型更关键&quot;">​</a></h3><p>无法读取真实日志、运行测试或获取正确目录时，更强模型也只能基于缺失信息推断。先修复环境，再判断是否需要换模型。</p><h3 id="_3-4-用团队真实任务建立基准" tabindex="-1">3.4 用团队真实任务建立基准 <a class="header-anchor" href="#_3-4-用团队真实任务建立基准" aria-label="Permalink to &quot;3.4 用团队真实任务建立基准&quot;">​</a></h3><p>比较完成率、人工修正、验证通过率、总耗时和成本，而不是只看单次演示。官方可用模型和推荐会变化，选择应定期重测。</p><p><img src="'+c+'" alt="图 3：复杂度、风险、工具与预算共同决定模型选择"></p><h2 id="四、推理强度不是越高越好" tabindex="-1">四、推理强度不是越高越好 <a class="header-anchor" href="#四、推理强度不是越高越好" aria-label="Permalink to &quot;四、推理强度不是越高越好&quot;">​</a></h2><p>较低强度适合范围明确、反馈快速的任务；较高强度适合需要计划、权衡和多轮工具验证的任务。盲目提高强度会增加延迟和成本，却无法修复错误上下文。</p><p>可以在代表性任务上比较多个档位，并把结果记录为团队经验。具体档位名称和模型支持情况以当前界面与官方文档为准。</p><h2 id="五、速度要看端到端链路" tabindex="-1">五、速度要看端到端链路 <a class="header-anchor" href="#五、速度要看端到端链路" aria-label="Permalink to &quot;五、速度要看端到端链路&quot;">​</a></h2><h3 id="_5-1-缩小搜索范围" tabindex="-1">5.1 缩小搜索范围 <a class="header-anchor" href="#_5-1-缩小搜索范围" aria-label="Permalink to &quot;5.1 缩小搜索范围&quot;">​</a></h3><p>指出入口、相关目录、错误日志和验证命令，是最便宜的加速方式。它减少无目的搜索和无关文件读取。</p><h3 id="_5-2-建立快速局部反馈" tabindex="-1">5.2 建立快速局部反馈 <a class="header-anchor" href="#_5-2-建立快速局部反馈" aria-label="Permalink to &quot;5.2 建立快速局部反馈&quot;">​</a></h3><p>先运行目标单元测试或静态检查，局部通过后再扩大验证。每轮全量构建会浪费时间，永远不跑集成验证又会遗漏风险。</p><h3 id="_5-3-使用可重建缓存" tabindex="-1">5.3 使用可重建缓存 <a class="header-anchor" href="#_5-3-使用可重建缓存" aria-label="Permalink to &quot;5.3 使用可重建缓存&quot;">​</a></h3><p>依赖缓存和构建产物能减少等待，但必须有失效规则。来源不明的旧缓存会制造假通过。</p><h3 id="_5-4-分离独立任务" tabindex="-1">5.4 分离独立任务 <a class="header-anchor" href="#_5-4-分离独立任务" aria-label="Permalink to &quot;5.4 分离独立任务&quot;">​</a></h3><p>互不依赖的调查或实现可以并行，修改同一接口的任务不应为了“多代理”强行并行。并行的收益来自独立性，不是代理数量。</p><p><img src="'+n+'" alt="图 4：检索、推理、工具、构建与 Review 组成总耗时"></p><h2 id="六、诊断配置问题要看实际生效值" tabindex="-1">六、诊断配置问题要看实际生效值 <a class="header-anchor" href="#六、诊断配置问题要看实际生效值" aria-label="Permalink to &quot;六、诊断配置问题要看实际生效值&quot;">​</a></h2><p>遇到行为与预期不一致，依次核对当前工作目录、加载的配置层、选中 Profile、模型与推理强度、权限模式、Feature 状态、MCP 和项目规则。不要只盯着某一个 <code>config.toml</code> 文件，因为更高优先级覆盖可能已经改变结果。</p><p><img src="'+s+'" alt="图 5：配置诊断从文件声明追踪到实际运行行为"></p><h2 id="七、配置治理的最终目标是可重建" tabindex="-1">七、配置治理的最终目标是可重建 <a class="header-anchor" href="#七、配置治理的最终目标是可重建" aria-label="Permalink to &quot;七、配置治理的最终目标是可重建&quot;">​</a></h2><p>团队成员和 CI 应能从版本化仓库、明确个人前置条件和官方当前版本重建同类行为。任何只有某台机器“碰巧能跑”的配置，都不是可靠工程能力。</p><p><img src="'+d+'" alt="图 6：版本化配置、项目规则与验证形成可重建环境"></p><h2 id="八、官方参考资料" tabindex="-1">八、官方参考资料 <a class="header-anchor" href="#八、官方参考资料" aria-label="Permalink to &quot;八、官方参考资料&quot;">​</a></h2><p><a href="https://learn.chatgpt.com/docs/config-file/config-basic" target="_blank" rel="noreferrer">OpenAI Docs：Config basics</a></p><p><a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">OpenAI Docs：Configuration Reference</a></p><p><a href="https://learn.chatgpt.com/docs/models" target="_blank" rel="noreferrer">OpenAI Docs：Model selection</a></p><p><a href="https://learn.chatgpt.com/docs/agent-configuration/speed" target="_blank" rel="noreferrer">OpenAI Docs：Speed</a></p>',55)])])}const q=a(p,[["render",h]]);export{x as __pageData,q as default};
